do $do$ declare v_jobid bigint; v_command text; begin select jobid,command into v_jobid,v_command from cron.job where jobname='geo_address_drain' and active and schedule='*/15 * * * *'; if v_jobid is null or position('''batch_size'', 5' in v_command)=0 then raise exception 'Unexpected geo_address_drain state; refusing to pause'; end if; perform cron.alter_job(v_jobid, active => false); end $do$;
